SELECT DISTINCTROW RECLAMI2.[Numero risposta], RECLAMI2.[Reclamo numero], RECLAMI2.Data, DATI.DESPROD, DATI.ANCLI_DESCLI, DATI.DATAENT, RECLAMI2.Difetto, RECLAMI2.Esterno
FROM DATI INNER JOIN RECLAMI2 ON DATI.NUMCOMM = RECLAMI2.Commessa
WHERE ((RECLAMI2.Data Like "*/01/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/02/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/03/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/04/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/05/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/06/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/07/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0)) OR ((RECLAMI2.Data Like "*/08/98") AND (RECLAMI2.Difetto Not Like "*51*" And RECLAMI2.Difetto Not Like "*35*" And RECLAMI2.Difetto Not Like "*40*" And RECLAMI2.Difetto Not Like "*55*") AND (RECLAMI2.Esterno Is Null) AND (RECLAMI2.[Duplicato di reclamo]=0));
